      const result = await iterator.next();
      if (result.done) {
        if (chunk.length > 0) {
          yield chunk;
        }
        break;
      }

      chunk.push(result.value);

      if (chunk.length === size) {
        yield chunk;
        chunk = [];
      }
    }
  } finally {
    if (iterator.return) {
      await iterator.return();
    }
  }
}

